E["28:a0fb253d"] = "Гномські пристрої та прилади."
E["28:a196f2e0"] = "Випадає з демонів і сатирів"
E["28:a53bd50a"] = "Лише персонажі цього сервера"
E["28:a5469b84"] = "Клік: продати торговцю"
E["28:a6498894"] = "Збір рахує вашу здобич"
E["28:a64c28b1"] = "Майстри гільдії, навіть не в мережі"
E["28:adad703a"] = "Бруднолипка трясовина та подібні"
E["28:b07bae70"] = "Виплавка в посібнику для професії Гірнича справа"
E["28:b1749a7a"] = "Крок посібника: немає у вашій грі"
E["28:b84d4c96"] = "Тут також з'являються олово й золото."
E["28:b99c370e"] = "Що ви носили перед риболовлею"
E["28:c32404c0"] = "!who у чаті гільдії та групи"
E["28:c8d01058"] = "Цей майстер не знає цього рецепта."
E["28:cff57a43"] = "Авто: найсильніша, яка у вас є"
E["28:d2b3e2a4"] = "жовтий - підвищення вміння здебільшого"
E["28:da050bd5"] = "Відстеження збору та інструменти"
E["28:e5f61041"] = "Принесіть усе, що потрібно для рецепта."
E["28:e84e52a9"] = "напр., ваші матеріали, чайові вітаються"
E["28:fd8ad8a7"] = "Здайте його у вашому торговому центрі"
E["290:5ee824cc"] = "Дивіться, хто на вашому сервері у мережі з Mastercraft, що вони можуть виготовити, і просіть одним кліком. Без шепотів і спаму: майстер отримує спливне вікно і відповідає «Прийняти», «Відхилити», «Принести матеріали», «Через 10 хвилин» або «Зустрінемось у моїй зоні» - а запрошення " ..
    "надсилається саме. Клавіша в розділі «Прив'язки клавіш» відкриває це вікно."
E["290:eabe11ca"] = "Мережу «Майстрів» перебудовано: усі у вашій фракції з цією версією зустрічаються в одному місці й знаходять одне одного, Mastercraft більше не показує поле для пароля й тримає всіх разом, коли гравець, який її розміщує, виходить із гри. Гравці зі старішою версією долучаться, щойно " ..
    "оновляться."
